    if (blockEntries.length === 0) return;
    var first = blockEntries[0];
    var second = blockEntries[1] || null;
    var detail = second
        ? 'lines ' + first.start + '-' + first.end + ' duplicate of ' +
          second.path + ':' + second.start + '-' + second.end
